CREATE TYPE "GaAngleStatus" AS ENUM ('PLANNED','INSPECTED','MATCH','GAP_FOUND','IT_ACTION','RECHECK','CLOSED');
CREATE TYPE "GaFindingStatus" AS ENUM ('OPEN','IN_PROGRESS','ESCALATED','RESOLVED','VERIFIED','CLOSED');
CREATE TYPE "GaReconciliationStatus" AS ENUM ('PENDING','MATCH','DISCREPANCY','RESOLVED','VERIFIED');
CREATE TABLE "GaCctvAngleInspection" ("id" SERIAL PRIMARY KEY,"cameraAssetId" INTEGER,"cameraName" TEXT NOT NULL,"areaId" INTEGER REFERENCES "GaArea"("id"),"plannedViewReference" TEXT,"actualViewPhoto" TEXT,"coverage" TEXT,"gapDescription" TEXT,"status" "GaAngleStatus" NOT NULL DEFAULT 'PLANNED',"inspectedAt" TIMESTAMP(3),"inspectorId" INTEGER NOT NULL,"ticketReference" TEXT,"reviewerId" INTEGER,"reviewedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "GaWeighbridgeReconciliation" ("id" SERIAL PRIMARY KEY,"ticketNumber" TEXT NOT NULL UNIQUE,"securityTime" TIMESTAMP(3) NOT NULL,"cctvTime" TIMESTAMP(3) NOT NULL,"cameraName" TEXT NOT NULL,"plateNumber" TEXT,"vehicleType" TEXT,"goodsType" TEXT,"durationMinutes" INTEGER,"checkerId" INTEGER NOT NULL,"status" "GaReconciliationStatus" NOT NULL DEFAULT 'PENDING',"discrepancyReason" TEXT,"verifiedById" INTEGER,"verifiedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "GaFinding" ("id" SERIAL PRIMARY KEY,"code" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"source" TEXT NOT NULL,"areaId" INTEGER REFERENCES "GaArea"("id"),"severity" TEXT NOT NULL DEFAULT 'MEDIUM',"status" "GaFindingStatus" NOT NULL DEFAULT 'OPEN',"assigneeId" INTEGER,"dueDate" TIMESTAMP(3),"containment" TEXT,"rootCause" TEXT,"correctiveAction" TEXT,"evidence" TEXT,"escalatedTicket" TEXT,"verifiedById" INTEGER,"verifiedAt" TIMESTAMP(3),"createdById" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
